<?php
if(!defined('ABSPATH')){exit;}
final class Orion_Manager_Queue_Admin{
 private Orion_Conversation_Service $conversations;private Orion_Knowledge_Base $knowledge;private Orion_Manager_Handoff $gaps;
 public function __construct(Orion_Conversation_Service $conversations,Orion_Knowledge_Base $knowledge){$this->conversations=$conversations;$this->knowledge=$knowledge;$this->gaps=new Orion_Manager_Handoff();}
 public function register():void{add_action('admin_post_orion_ai_update_gap',array($this,'handle_update'));}
 public function render():void{if(!current_user_can('manage_woocommerce'))return;$selected=absint($_GET['gap_id']??0);$status=sanitize_key(wp_unslash($_GET['gap_status']??''));$reason=sanitize_key(wp_unslash($_GET['gap_reason']??''));$filters=array();if(Orion_Manager_Queue_Policy::is_status($status))$filters['status']=$status;if($reason!=='')$filters['reason_code']=$reason;$item=$selected?$this->gaps->get($selected):null;$items=$item?array($item):$this->gaps->all(150,$filters);echo '<section class="orion-card orion-gaps"><h2>AI knowledge gaps</h2><p>These are requests Orion could not answer safely. Review the full conversation, write verified guidance, optionally attach a source, and explicitly add only that reviewed guidance to the knowledge base. Customer text is never published automatically.</p>';$this->counts($status);$this->filters($status,$reason);if($selected)echo '<p><a href="'.esc_url(add_query_arg(array('page'=>'orion-ai-assistant','tab'=>'gaps'),admin_url('admin.php'))).'">← Back to all gaps</a></p>';if(!$items)echo '<p>No knowledge gaps match these filters.</p>';foreach($items as$row)$this->item($row);echo '</section><style>.orion-admin .orion-gaps{max-width:1200px}.orion-gap-counts{display:flex;flex-wrap:wrap;gap:8px;margin:18px 0}.orion-gap-count{padding:7px 11px;border:1px solid #c3c4c7;border-radius:999px;background:#fff;text-decoration:none}.orion-gap-count.is-active{border-color:#2271b1;background:#f0f6fc}.orion-gap-filters{display:flex;gap:12px;align-items:end;flex-wrap:wrap;padding:14px;background:#f6f7f7;border:1px solid #dcdcde;border-radius:8px}.orion-gap-filters label{display:grid;gap:4px}.orion-gap{margin-top:16px;padding:18px;border:1px solid #dcdcde;border-left:5px solid #dba617;border-radius:8px;background:#fff}.orion-gap.is-resolved{border-left-color:#00a32a}.orion-gap.is-dismissed{border-left-color:#787c82}.orion-gap-meta{display:flex;gap:8px;flex-wrap:wrap}.orion-gap-badge{display:inline-block;padding:3px 8px;border-radius:999px;background:#f0f0f1;font-size:12px}.orion-gap-form{display:grid;gap:12px;margin-top:16px;padding-top:16px;border-top:1px solid #eee}.orion-gap-form textarea{width:100%;min-height:120px}.orion-gap-actions{display:flex;gap:8px;flex-wrap:wrap}</style>';}
 private function counts(string $active):void{$counts=$this->gaps->counts();echo '<div class="orion-gap-counts">';$this->count_link('','All',array_sum($counts),$active==='');foreach(Orion_Manager_Queue_Policy::statuses()as$status)$this->count_link($status,$this->label($status),(int)($counts[$status]??0),$active===$status);echo '</div>';}
 private function count_link(string $status,string $label,int $count,bool $active):void{$args=array('page'=>'orion-ai-assistant','tab'=>'gaps');if($status!=='')$args['gap_status']=$status;echo '<a class="orion-gap-count '.($active?'is-active':'').'" href="'.esc_url(add_query_arg($args,admin_url('admin.php'))).'">'.esc_html($label).' <strong>'.$count.'</strong></a>';}
 private function filters(string $status,string $reason):void{$reasons=$this->gaps->reason_counts();echo '<form class="orion-gap-filters" method="get" action="'.esc_url(admin_url('admin.php')).'"><input type="hidden" name="page" value="orion-ai-assistant"><input type="hidden" name="tab" value="gaps"><label><strong>Status</strong><select name="gap_status"><option value="">All statuses</option>';foreach(Orion_Manager_Queue_Policy::statuses()as$value)echo '<option value="'.esc_attr($value).'" '.selected($status,$value,false).'>'.esc_html($this->label($value)).'</option>';echo '</select></label><label><strong>Reason</strong><select name="gap_reason"><option value="">All reasons</option>';foreach($reasons as$row){$value=(string)$row['reason_code'];echo '<option value="'.esc_attr($value).'" '.selected($reason,$value,false).'>'.esc_html(str_replace('_',' ',$value)).' ('.(int)$row['total'].')</option>';}echo '</select></label><button class="button">Filter</button><a class="button" href="'.esc_url(add_query_arg(array('page'=>'orion-ai-assistant','tab'=>'gaps'),admin_url('admin.php'))).'">Reset</a></form>';}
 private function item(array $item):void{$id=(int)$item['id'];$status=(string)$item['status'];$trace=absint($item['trace_id']??0);$conversation=absint($item['conversation_id']??0);$context=json_decode((string)($item['context_json']??''),true);$context=is_array($context)?$context:array();echo '<article class="orion-gap is-'.esc_attr($status).'"><div style="display:flex;justify-content:space-between;gap:16px"><div><h3 style="margin:0">Knowledge gap #'.$id.'</h3><div class="orion-gap-meta"><span class="orion-gap-badge">'.esc_html($this->label($status)).'</span><span class="orion-gap-badge">'.esc_html(str_replace('_',' ',(string)$item['reason_code'])).'</span></div></div><small>'.esc_html((string)$item['created_at']).'</small></div><p style="font-size:15px;line-height:1.55">'.nl2br(esc_html((string)$item['question'])).'</p><p>';$conversation_url=add_query_arg(array('page'=>'orion-ai-assistant','tab'=>'conversations','conversation_id'=>$conversation),admin_url('admin.php'));echo '<a class="button button-small" href="'.esc_url($conversation_url).'">Open full conversation #'.$conversation.'</a> ';if($trace){$trace_url=add_query_arg(array('page'=>'orion-ai-assistant','tab'=>'traces','trace_id'=>$trace),admin_url('admin.php'));echo '<a class="button button-small" href="'.esc_url($trace_url).'">Open trace #'.$trace.'</a>';}echo '</p>';if($context)echo '<details><summary>Diagnostic context</summary><pre style="white-space:pre-wrap;max-height:360px;overflow:auto">'.esc_html(wp_json_encode($context,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)).'</pre></details>';if(!empty($item['knowledge_document_id'])){echo '<div class="notice notice-success inline"><p>Added to knowledge base as document #'.(int)$item['knowledge_document_id'].' on '.esc_html((string)$item['knowledge_published_at']).'.</p></div>';}$this->form($item);$this->history($id);echo '</article>';}
 private function form(array $item):void{$id=(int)$item['id'];$status=(string)$item['status'];echo '<form class="orion-gap-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('orion_ai_update_gap_'.$id);echo '<input type="hidden" name="action" value="orion_ai_update_gap"><input type="hidden" name="gap_id" value="'.$id.'"><label><strong>Knowledge title</strong><input class="widefat" maxlength="240" name="knowledge_title" value="'.esc_attr((string)($item['knowledge_title']??'')).'" placeholder="Example: Warranty information for power tools"></label><label><strong>Verified guidance</strong><textarea name="verified_guidance" maxlength="12000" placeholder="Write only confirmed facts that the AI may use for future questions.">'.esc_textarea((string)($item['resolution_note']??'')).'</textarea><span class="description">Required before publishing. Do not copy unverified customer claims.</span></label><label><strong>Source URL (optional)</strong><input class="widefat" type="url" name="knowledge_source_url" value="'.esc_attr((string)($item['knowledge_source_url']??'')).'" placeholder="https://manufacturer.example/documentation"><span class="description">The link is stored as evidence; external pages are not fetched automatically.</span></label><div class="orion-gap-actions">';if(!Orion_Manager_Queue_Policy::is_terminal($status)){echo '<button class="button" name="gap_action" value="save">Save review</button><button class="button button-primary" name="gap_action" value="publish" onclick="return confirm(\'Add only this reviewed guidance to the AI knowledge base?\')">Add to knowledge base</button><button class="button button-link-delete" name="gap_action" value="ignore">Ignore gap</button>';}else echo '<button class="button button-primary" name="gap_action" value="reopen">Reopen</button>';echo '</div></form>';}
 public function handle_update():void{if(!current_user_can('manage_woocommerce'))wp_die('Forbidden');$id=absint($_POST['gap_id']??0);check_admin_referer('orion_ai_update_gap_'.$id);$item=$this->gaps->get($id);if(!$item)$this->redirect('Knowledge gap was not found.');$action=sanitize_key(wp_unslash($_POST['gap_action']??'save'));$title=mb_substr(sanitize_text_field(wp_unslash($_POST['knowledge_title']??'')),0,240);$guidance=mb_substr(trim(wp_kses_post(wp_unslash($_POST['verified_guidance']??''))),0,12000);$source=esc_url_raw(trim((string)wp_unslash($_POST['knowledge_source_url']??'')));$user=get_current_user_id();$conversation=(int)$item['conversation_id'];if($action==='save'){$ok=$this->gaps->save_review($id,$title,$guidance,$source,$user);if($ok)$this->conversations->record_event('knowledge_gap_reviewed',array('gap_id'=>$id,'actor_user_id'=>$user),$conversation);$this->redirect($ok?'Review saved.':'The review could not be saved.');}if($action==='publish'){if($title===''||mb_strlen(trim(wp_strip_all_tags($guidance)))<20)$this->redirect('Enter a knowledge title and at least 20 characters of verified guidance.');if(!$this->gaps->save_review($id,$title,$guidance,$source,$user))$this->redirect('The review could not be saved.');$markdown=$guidance;if($source!=='')$markdown.="\n\nSource: [".$source."](".$source.")";$result=$this->knowledge->create_manual($title,$markdown);if(empty($result['ok']))$this->redirect((string)$result['message']);$document_id=0;$hash=hash('sha256',wp_kses_post(wp_unslash($markdown)));foreach($this->knowledge->all()as$document){if((string)$document['title']===$title&&(string)$document['content_hash']===$hash){$document_id=(int)$document['id'];break;}}if(!$document_id||!$this->gaps->mark_knowledge_added($id,$document_id,$user)){if($document_id)$this->knowledge->delete_document($document_id);$this->redirect('Knowledge was indexed but the gap could not be linked; the temporary document was removed.');}$this->conversations->record_event('knowledge_gap_published',array('gap_id'=>$id,'document_id'=>$document_id,'actor_user_id'=>$user),$conversation);$this->redirect('Verified guidance added and indexed in the knowledge base.');}if($action==='ignore'){$ok=$this->gaps->transition($id,Orion_Manager_Queue_Policy::STATUS_DISMISSED,$user);if($ok)$this->conversations->record_event('knowledge_gap_ignored',array('gap_id'=>$id,'actor_user_id'=>$user),$conversation);$this->redirect($ok?'Knowledge gap ignored.':'The gap could not be ignored.');}if($action==='reopen'){$ok=$this->gaps->transition($id,Orion_Manager_Queue_Policy::STATUS_NEW,$user);$this->redirect($ok?'Knowledge gap reopened.':'The gap could not be reopened.');}$this->redirect('Unknown action.');}
 private function history(int $id):void{$history=$this->gaps->history($id,30);if(!$history)return;echo '<details><summary>Review history</summary><ul>';foreach($history as$event){$uid=absint($event['user_id']??0);$user=$uid?get_userdata($uid):false;$actor=$user?$user->display_name:($uid?'User #'.$uid:'System');echo '<li><strong>'.esc_html(str_replace('_',' ',(string)$event['event_type'])).'</strong> · '.esc_html($actor).' · '.esc_html((string)$event['created_at']).'</li>';}echo '</ul></details>';}
 private function redirect(string $message):void{wp_safe_redirect(add_query_arg(array('page'=>'orion-ai-assistant','tab'=>'gaps','orion_notice'=>$message),admin_url('admin.php')));exit;}
 private function label(string $status):string{return array('new'=>'New','in_progress'=>'Reviewing','resolved'=>'Added to knowledge','dismissed'=>'Ignored')[$status]??ucwords(str_replace('_',' ',$status));}
}
